const body = ($('Webhook').first().json.body) || {};
const customerName = (body.customerName || '').toString().trim();
const requested = (body.item || '').toString().trim();
const rows = $input.all().map(i => i.json);
const norm = (s) => (s || '').toString().toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const orderDate = $now;
const deliveryDate = $now.plus({ days: 2 });
const orderDateFmt = orderDate.toFormat('dd LLL yyyy, HH:mm');
const deliveryDateFmt = deliveryDate.toFormat('dd LLL yyyy');
const rand = Math.floor(1000 + Math.random() * 9000);
const orderId = 'ORD-' + orderDate.toFormat('yyyyLLdd') + '-' + rand;
const availableItems = rows.map(r => r.name).filter(Boolean);
const base = (extra) => Object.assign({ customerName, requestedItem: requested, orderId, orderDateFmt, deliveryDateFmt, availableItems }, extra);
if (!customerName || !requested) { return [{ json: base({ status: 'missing_input', message: 'I still need both your name and the item you want.' }) }]; }
const rq = norm(requested);
let best = null, bestScore = 0;
for (const r of rows) {
  const nm = norm(r.name);
  if (!nm) continue;
  let score = 0;
  if (nm === rq) score = 100;
  else if (nm.indexOf(rq) >= 0 || rq.indexOf(nm) >= 0) score = 80;
  else { const a = rq.split(' ').filter(Boolean); const b = nm.split(' ').filter(Boolean); let overlap = 0; for (const t of a) if (b.indexOf(t) >= 0) overlap++; if (a.length) score = Math.round((overlap / a.length) * 70); }
  if (score > bestScore) { bestScore = score; best = r; }
}
if (!best || bestScore < 40) { return [{ json: base({ status: 'not_found', message: 'I could not find that item in the catalog.' }) }]; }
const stock = Number(best.stock);
const price = best.price_pkr;
if (!isNaN(stock) && stock <= 0) { return [{ json: base({ status: 'out_of_stock', productName: best.name, sku: best.sku, price, message: best.name + ' is out of stock right now.' }) }]; }
return [{ json: base({ status: 'ok', productName: best.name, sku: best.sku, price, stock, matchScore: bestScore, message: 'Order confirmed.' }) }];

const d = $input.first().json;
const esc = (s) => (s == null ? '' : String(s)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let h = '';
h += '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">';
h += '<title>Order Slip ' + esc(d.orderId) + '</title></head>';
h += '<body style="margin:0;background:#f4f5f7;font-family:Arial,Helvetica,sans-serif;color:#1a1a2e;">';
h += '<div style="max-width:560px;margin:24px auto;background:#fff;border-radius:14px;overflow:hidden;box-shadow:0 6px 24px rgba(0,0,0,.08);">';
h += '<div style="background:#1a1a2e;color:#fff;padding:22px 26px;"><div style="font-size:20px;font-weight:700;">Mobile Accessories</div>';
h += '<div style="opacity:.75;font-size:13px;margin-top:2px;">Order Confirmation Slip</div></div>';
h += '<div style="padding:24px 26px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">';
h += '<tr><td style="padding:8px 0;color:#6b7280;">Order ID</td><td style="padding:8px 0;text-align:right;font-weight:600;">' + esc(d.orderId) + '</td></tr>';
h += '<tr><td style="padding:8px 0;color:#6b7280;">Customer</td><td style="padding:8px 0;text-align:right;font-weight:600;">' + esc(d.customerName) + '</td></tr>';
h += '<tr><td style="padding:8px 0;color:#6b7280;">Order Date</td><td style="padding:8px 0;text-align:right;">' + esc(d.orderDateFmt) + '</td></tr></table>';
h += '<div style="border-top:1px dashed #d1d5db;margin:14px 0;"></div><table style="width:100%;border-collapse:collapse;font-size:14px;">';
h += '<tr><td style="padding:8px 0;color:#6b7280;">Item</td><td style="padding:8px 0;text-align:right;font-weight:600;">' + esc(d.productName) + '</td></tr>';
h += '<tr><td style="padding:8px 0;color:#6b7280;">SKU</td><td style="padding:8px 0;text-align:right;">' + esc(d.sku) + '</td></tr>';
h += '<tr><td style="padding:8px 0;color:#6b7280;">Quantity</td><td style="padding:8px 0;text-align:right;">1</td></tr></table>';
h += '<div style="border-top:1px dashed #d1d5db;margin:14px 0;"></div><table style="width:100%;border-collapse:collapse;font-size:15px;">';
h += '<tr><td style="padding:10px 0;font-weight:700;">Total</td><td style="padding:10px 0;text-align:right;font-weight:700;color:#16a34a;">PKR ' + esc(d.price) + '</td></tr></table>';
h += '<div style="background:#eef2ff;border-radius:10px;padding:14px 16px;margin-top:14px;font-size:14px;">Estimated delivery<span style="float:right;font-weight:700;">' + esc(d.deliveryDateFmt) + ' (2 days)</span></div>';
h += '</div><div style="padding:14px 26px;background:#fafafa;color:#9ca3af;font-size:12px;text-align:center;">Thank you for your order!</div></div></body></html>';
return [{ json: Object.assign({}, d, { slipHtml: h }) }];

const d = $('Match & Validate').first().json;
const slipId = $('Create Slip File').first().json.id;
return [{ json: { status: 'ok', orderId: d.orderId, customerName: d.customerName, productName: d.productName, sku: d.sku, price: d.price, currency: 'PKR', orderDate: d.orderDateFmt, deliveryDate: d.deliveryDateFmt, slipViewUrl: 'https://drive.google.com/file/d/' + slipId + '/view', slipDownloadUrl: 'https://drive.google.com/uc?export=download&id=' + slipId, message: 'Order ' + d.orderId + ' confirmed for ' + d.customerName + '. Delivery by ' + d.deliveryDateFmt + '.' } }];
